# =========================================================
# API HELPER FUNCTIONS WITH AUTH
# =========================================================


def get_headers():
    return {
        "Authorization": f"Bearer {JWT_TOKEN}",
        "Content-Type": "application/json",
    }


def open_barrier_gate(gate_name):
    """Sends request to open barrier gate."""
    url = f"{SIMULATOR_BASE_URL}/barrier-gates/{gate_name}/open"
    try:
        response = requests.post(url, headers=get_headers(), timeout=2)
        print(f"OPEN GATE ({gate_name}): HTTP {response.status_code}")
    except requests.RequestException as e:
        print(f"Error opening gate {gate_name}:", e)


def close_barrier_gate(gate_name):
    """Sends request to close barrier gate."""
    url = f"{SIMULATOR_BASE_URL}/barrier-gates/{gate_name}/close"
    try:
        response = requests.post(url, headers=get_headers(), timeout=2)
        print(f"CLOSE GATE ({gate_name}): HTTP {response.status_code}")
    except requests.RequestException as e:
        print(f"Error closing gate {gate_name}:", e)


def initialize_gates():
    """Forces all gates to start in a closed state to prevent them from being left open."""
    print("Initializing gates to CLOSED state...")
    close_barrier_gate(ENTRY_GATE_NAME)
    close_barrier_gate(EXIT_GATE_NAME)


def charge_car_and_open_exit(plate, car_type):
    """Calculates fee, bills the car, opens the exit gate, and uses rapid-fire to guarantee instant exit."""
    global total_revenue
    
    with duration_lock:
        entry_time = car_entry_times.get(plate, time.time() - 60)
        
    duration_sec = time.time() - entry_time
    minutes_spent = max(1, int(duration_sec / 60))

    parking_cost = float(minutes_spent)
    charging_cost = float(minutes_spent) if car_type == "Electric" else 0.0
    total_bill = parking_cost + charging_cost

    with duration_lock:
        total_revenue += total_bill

    charge_url = f"{SIMULATOR_BASE_URL}/car/{plate}/charge?parkingCost={parking_cost}&chargingCost={charging_cost}"
    
    try:
        requests.post(charge_url, headers=get_headers(), timeout=2)
        print(f"CHARGE CAR {plate} Total: ${total_bill} (Park: {parking_cost}, Charge: {charging_cost})")
        
        open_barrier_gate(EXIT_GATE_NAME)
        
        leave_url = f"{SIMULATOR_BASE_URL}/car/{plate}/goto/leavepark"
        
        # RAPID-FIRE EXIT LOGIC
        # Spams the move command every 0.1 seconds so the car moves the instant the gate allows it
        for _ in range(15):
            try:
                requests.post(leave_url, headers=get_headers(), timeout=1)
            except:
                pass
            time.sleep(0.1)

    except requests.RequestException as e:
        print(f"Error during exit sequence for car {plate}:", e)


# =========================================================
# DATABASE SETUP & HELPERS
# =========================================================


def init_database():
    connection = sqlite3.connect("parking.db")
    cursor = connection.cursor()
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS webhook_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id TEXT UNIQUE,
            sequence_id INTEGER,
            event_class TEXT,
            car_plate TEXT,
            car_type TEXT,
            spot_name TEXT,
            spot_type TEXT,
            direction TEXT,
            amount TEXT,
            reason TEXT,
            server_datetime TEXT,
            raw_data TEXT
        )
    """)
    connection.commit()
    connection.close()


def event_already_exists(event_id):
    if event_id is None:
        return False
    connection = sqlite3.connect("parking.db")
    cursor = connection.cursor()
    cursor.execute(
        "SELECT event_id FROM webhook_events WHERE event_id = ?", (event_id,)
    )
    result = cursor.fetchone()
    connection.close()
    return result is not None


def save_event(data):
    connection = sqlite3.connect("parking.db")
    cursor = connection.cursor()
    cursor.execute(
        """
        INSERT INTO webhook_events (
            event_id, sequence_id, event_class, car_plate, car_type,
            spot_name, spot_type, direction, amount, reason,
            server_datetime, raw_data
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """,
        (
            data.get("EventId"),
            data.get("SequenceId"),
            data.get("EventClass"),
            data.get("CarPlateNumber"),
            data.get("CarType"),
            data.get("SpotName"),
            data.get("SpotType"),
            data.get("Direction"),
            data.get("Amount"),
            data.get("Reason"),
            data.get("ServerDateTime"),
            json.dumps(data),
        ),
    )
    connection.commit()
    connection.close()


def get_recent_events():
    connection = sqlite3.connect("parking.db")
    connection.row_factory = sqlite3.Row
    cursor = connection.cursor()
    cursor.execute("""
        SELECT id, sequence_id, event_class, car_plate, car_type,
               spot_name, spot_type, direction, amount, reason, server_datetime
        FROM webhook_events ORDER BY id DESC LIMIT 100
    """)
    events = cursor.fetchall()
    connection.close()
    return events


# =========================================================
# AUTO-PARK LOGIC
# =========================================================


def reserve_free_spot(plate):
    with spot_lock:
        for spot in PARK_SPOTS:
            if spot not in spot_state:
                spot_state[spot] = plate
                return spot
    return None


def release_spot(spot_name):
    with spot_lock:
        spot_state.pop(spot_name, None)


def auto_park_car(plate, entry_spot):
    spot = reserve_free_spot(plate)
    if spot is None:
        print(f"NO FREE SPOT for {plate}")
        return

    open_barrier_gate(ENTRY_GATE_NAME)
    url = f"{SIMULATOR_BASE_URL}/car/{plate}/goto/{spot}"

    # RAPID-FIRE ENTRY LOGIC
    # Spams the move command 15 times so the car enters instantly regardless of GlobalSpeed
    for _ in range(15):
        try:
            requests.post(url, headers=get_headers(), timeout=1)
        except:
            pass
        time.sleep(0.1)


