@app.route("/webhook", methods=["POST"])
def receive_webhook():
    global last_sequence_id
    data = request.get_json(silent=True)

    if data is None:
        return jsonify({"status": "invalid json"}), 400

    event_id = data.get("EventId")
    sequence_id = data.get("SequenceId")
    event_class = data.get("EventClass")

    if event_already_exists(event_id):
        return jsonify({"status": "duplicate ignored"}), 200

    if sequence_id is not None:
        if last_sequence_id is not None and sequence_id != last_sequence_id + 1:
            print(f"WARNING: Sequence gap! Expected {last_sequence_id + 1}, got {sequence_id}")
        last_sequence_id = sequence_id

    try:
        save_event(data)
    except Exception as error:
        print("DATABASE ERROR:", error)

    # Handlers
    if event_class == "car_spot_action":
        plate = data.get("CarPlateNumber")
        car_type = data.get("CarType")
        spot_name = data.get("SpotName")
        spot_type = data.get("SpotType")
        direction = data.get("Direction")

        # --- ENTRY LOGIC ---
        if spot_type == "EntrySpot" and direction == "CarIn":
            print(f"NEW CAR ARRIVED: {plate}")
            with duration_lock:
                car_entry_times[plate] = time.time()
            threading.Thread(
                target=auto_park_car, args=(plate, spot_name), daemon=True
            ).start()

        elif spot_type == "EntrySpot" and direction == "CarOut":
            print(f"CAR PASSED ENTRY: {plate}. Closing Gate...")
            threading.Thread(
                target=close_barrier_gate, args=(ENTRY_GATE_NAME,), daemon=True
            ).start()

        # --- PARKING LOGIC ---
        elif spot_type == "Park" and direction == "CarIn":
            print(f"CAR PARKED: {plate} at {spot_name}")
            with spot_lock:
                spot_state[spot_name] = plate

        elif spot_type == "Park" and direction == "CarOut":
            print(f"CAR LEFT SPOT: {plate} from {spot_name}")
            release_spot(spot_name)

        # --- EXIT LOGIC ---
        elif spot_type == "ExitSpot" and direction == "CarIn":
            print(f"CAR ARRIVED AT EXIT: {plate}")
            threading.Thread(
                target=charge_car_and_open_exit, args=(plate, car_type), daemon=True
            ).start()

        elif spot_type == "ExitSpot" and direction == "CarOut":
            print(f"CAR LEFT THE CAR PARK: {plate}. Closing Gate...")
            
            with duration_lock:
                if plate in car_entry_times:
                    duration_sec = time.time() - car_entry_times[plate]
                    completed_durations.append(duration_sec)
                    del car_entry_times[plate]

            threading.Thread(
                target=close_barrier_gate, args=(EXIT_GATE_NAME,), daemon=True
            ).start()

    return jsonify({"status": "received"}), 200


